#!/usr/bin/env python3
"""Generate buildless profile pages and the directory roster from reviewed JSON."""
from pathlib import Path
import json,re,html
ROOT=Path(__file__).resolve().parents[1]
def esc(text):return html.escape(str(text),quote=True)
people=json.loads((ROOT/'data/people-profiles.json').read_text())
translations=json.loads((ROOT/'data/profile-translations.json').read_text())
for person in people:
 for text in [*person['bio'], person['summary']]:
  assert all(translations.get(text,{}).get(lang) for lang in ['es','zh-Hans','hi','ar']), f"Missing biography translation: {person['slug']}"
(ROOT/'profile-translations.js').write_text('// Generated by scripts/build_people_pages.py.\nObject.assign(window.LAB_TRANSLATIONS, '+json.dumps(translations,ensure_ascii=False,indent=2)+');\n')
index=(ROOT/'index.html').read_text()
header=re.search(r'  <div class="institution-bar">.*?</header>',index,re.S).group()
header=re.sub(r'href="#(.*?)"',r'href="../index.html#\1"',header)
header=header.replace('src="assets/','src="../assets/')
footer=re.search(r'  <footer>.*?</footer>',index,re.S).group().replace('href="#home"','href="../index.html#people"')
main_pubs=[
('2026 · Biological Psychiatry','Biophysical modeling of excitation/inhibition balance and conversion to psychosis in the clinical high risk syndrome','https://doi.org/10.1016/j.biopsych.2026.04.007'),
('2026 · Schizophrenia Bulletin','Metabolic Improvements with a Ketogenic Diet Correlate with Symptom Improvement in Psychosis: A Randomized Controlled Trial','https://doi.org/10.1093/schbul/sbag082'),
('2026 · bioRxiv · Preprint','No objective evidence of neuropsychological deficits in people with subjective cognitive changes following COVID-19 infection','https://doi.org/10.64898/2026.06.03.723612'),
('2025 · Schizophrenia','The electroencephalography protocol for the Accelerating Medicines Partnership® Schizophrenia Program: Reliability and stability of measures','https://doi.org/10.1038/s41537-025-00622-0')]
main_pubs.append(('2026 · Biological Psychiatry', 'Visual P300 and Risk for Psychosis Onset in Youth at Clinical High Risk', 'https://doi.org/10.1016/j.biopsych.2026.02.013'))
selection={'daniel-mathalon':[0,3],'judith-ford':[1,2],'susanna-fryer':[1],'samantha-abram':[1,2],'michael-jacob':[1],'juliette-kyner':[1],'spero-nicholas':[3],'holly-hamilton':[4,0,3],'brian-roach':[3]}
roster=[]
for person in people:
 p=person;slug=p['slug'];full=p['name']+(', '+p['degree'] if p['degree'] else '')
 photo=(f'<img src="../{esc(p["portrait"])}" alt="Portrait of {esc(p["name"])}">' if p['portrait'] else f'<div class="profile-monogram" aria-hidden="true">{"".join(x[0] for x in p["name"].split())}</div><p class="small-label">Photo to come</p>')
 links=''.join(f'<a href="{esc(url)}">{esc(label)} <span aria-hidden="true">↗</span></a>' for label,url in p['links'])
 badge='<span class="draft-badge">Draft biography</span>' if p['draft'] else ''
 if p.get('provisional'):badge+='<span class="draft-badge">Provisional title</span>'
 blocks='<section class="profile-section"><h2>Biography</h2><div class="profile-prose" data-localized>' + ''.join(f'<p>{esc(x)}</p>' for x in p['bio'])+'</div></section>'
 # Education is stored in most-recent-first order; retain undated career ordering.
 if p['education']:
  blocks+='<section class="profile-section"><h2>Education and training</h2><dl class="training-list" lang="en" dir="ltr" data-original-language>'+''.join(f'<div><dt>{esc(institution)}</dt><dd>{esc(qualification)}'+(f' <span>{esc(year)}</span>' if year else '')+'</dd></div>' for institution,qualification,year in p['education'])+'</dl></section>'
 if p['awards']:
  blocks+='<section class="profile-section"><h2>Awards and honors</h2><ul class="profile-list" lang="en" dir="ltr" data-original-language>'+''.join(f'<li>{esc(award)} · {esc(institution)} · {esc(year)}</li>' for institution,award,year in p['awards'])+'</ul></section>'
 if p['projects']:
  blocks+='<section class="profile-section"><h2>Selected research projects</h2><p class="profile-caption">Dates reflect the source records; project listings do not indicate recruitment.</p><ul class="project-list" lang="en" dir="ltr" data-original-language>'+''.join(f'<li><h3>{esc(title)}</h3><p>{esc(dates)} · {esc(grant)}</p></li>' for title,dates,grant in p['projects'])+'</ul></section>'
 pubs=[main_pubs[i] for i in selection.get(slug,[])]
 if slug=='carlos-daniel-carrasco':pubs=[('2025 · Psychophysiology','Enhanced Working Memory Representations for Rare Events','https://doi.org/10.1111/psyp.70038'),('2024 · Psychophysiology','Using multivariate pattern analysis to increase effect sizes for event-related potential analyses','https://doi.org/10.1111/psyp.14570')]
 if pubs:
  blocks+='<section class="profile-section"><h2>Selected publications</h2><div lang="en" dir="ltr" data-original-language>'+''.join(f'<article class="profile-publication"><p class="publication-meta">{esc(meta)}</p><h3><a href="{esc(url)}">{esc(title)} ↗</a></h3></article>' for meta,title,url in pubs)+'</div></section>'
 blocks+='<section class="profile-section profile-sources"><h2>Profile sources</h2><p class="profile-caption" lang="en" dir="ltr" data-original-language>'+esc(p['sourceNote'])+'</p><ul>'+''.join(f'<li><a href="{esc(url)}">{esc(__import__("urllib.parse",fromlist=["urlparse"]).urlparse(url).netloc)} <span aria-hidden="true">↗</span></a></li>' for url in p['sources'])+'</ul></section>'
 interests='<ul class="interest-list" lang="en" dir="ltr" data-original-language>'+''.join(f'<li>{esc(x)}</li>' for x in p['interests'])+'</ul>' if p['interests'] else ''
 position=f'<p class="profile-academic" lang="en" dir="ltr" data-original-language>{esc(p["academic"])}</p>' if p['academic'] else ''
 source_note=''
 contents=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#052049"><meta name="description" content="{esc(p['summary'])}"><title>{esc(full)} · BIEEGL</title><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../styles.css?v=anchor-framing"><script src="../translations.js?v=profile-i18n" defer></script><script src="../profile-translations.js?v=profile-i18n" defer></script><script src="../script.js?v=anchor-framing" defer></script></head><body>
<a class="skip-link" href="#main">Skip to content</a>
{header}
<main id="main" class="container profile-main"><a class="profile-back" href="../index.html#people">← Back to the lab directory</a><div class="profile-heading"><p class="eyebrow">{esc(p['group'])}</p><h1>{esc(p['name'])}<span class="profile-degrees">{esc(p['degree'])}</span></h1><p class="profile-role">{esc(p['role'])}</p>{position}{badge}{source_note}</div><div class="profile-layout"><aside class="profile-sidebar"><div class="profile-portrait">{photo}</div>{('<h2>Research interests</h2>'+interests) if interests else ''}<div class="profile-links">{links}</div></aside><div class="profile-content">{blocks}</div></div><nav class="profile-neighbors" aria-label="More lab members">{('' if people.index(p)==0 else '<a href="'+people[people.index(p)-1]['slug']+'.html">← '+esc(people[people.index(p)-1]['name'])+'</a>')}<a href="../index.html#people">All lab members</a>{('' if people.index(p)==len(people)-1 else '<a href="'+people[people.index(p)+1]['slug']+'.html">'+esc(people[people.index(p)+1]['name'])+' →</a>')}</nav></main>
{footer}
</body></html>'''
 (ROOT/'people').mkdir(exist_ok=True);(ROOT/'people'/f'{slug}.html').write_text(contents)
 roster.append(dict(name=p['name'],role=p['role'],group=p['group'],portrait=p['portrait'],bio=p['summary'],profile=p['profile'],draft=p['draft'],provisional=p.get('provisional',False)))
(ROOT/'content.js').write_text('// Generated by scripts/build_people_pages.py from data/people-profiles.json.\nwindow.LAB_PEOPLE = '+json.dumps(roster,ensure_ascii=False,indent=2)+';\n')
print(f'Generated {len(people)} profile pages and directory entries.')
